const row = $input.first()?.json;
if (!row) {
  return [{ json: { prospectId: null, halted: false, timeline: [] } }];
}

const steps = row.steps || [];
const events = row.events || [];

function delayMs(value, unit) {
  const n = Number(value) || 0;
  return unit === 'days' ? n * 24 * 60 * 60 * 1000 : n * 60 * 60 * 1000;
}

// Every action that can fail reports the reason under a different key
// (LinkedIn actions: skippedReason; Brevo: message; a raw network error from
// onError:continueRegularOutput: error) - normalize to one field so the UI
// doesn't need to know which action produced it.
function failureReason(payload) {
  if (!payload) return null;
  return payload.skippedReason || payload.message || payload.error || null;
}

// The dispatch record for a step is always 'sent' or 'skipped' (written by
// linkedin-dispatch/email-send's Insert Event) - a step can pick up further
// downstream events later (e.g. a manually-recorded 'accepted') that are
// newer but aren't the dispatch outcome, so only 'sent'/'skipped' count here.
const eventsByStep = new Map();
for (const e of events) {
  if (e.eventType !== 'sent' && e.eventType !== 'skipped') continue;
  const existing = eventsByStep.get(e.stepId);
  if (!existing || new Date(e.occurredAt) > new Date(existing.occurredAt)) {
    eventsByStep.set(e.stepId, e);
  }
}

// Anchor for the first not-yet-happened step is the most recent event of any
// kind (or prospect creation if nothing has fired yet) - matches
// daily-scheduler's own due-check formula exactly. Steps after that chain
// off each other's projected time, since every step now proceeds on a fixed
// delay regardless of success/failure.
let cursor = events.length > 0 ? events[events.length - 1].occurredAt : row.createdAt;

const timeline = steps.map((step) => {
  const event = eventsByStep.get(step.id);
  if (event) {
    const isSent = event.eventType === 'sent';
    return {
      stepId: step.id,
      name: step.name,
      actionType: step.actionType,
      status: isSent ? 'completed' : 'skipped',
      eventType: event.eventType,
      occurredAt: event.occurredAt,
      dueAt: null,
      reason: isSent ? null : failureReason(event.payload),
    };
  }

  const isCurrent = step.id === row.currentStepId;
  const dueAt = new Date(new Date(cursor).getTime() + delayMs(step.delayValue, step.delayUnit)).toISOString();
  cursor = dueAt;

  return {
    stepId: step.id,
    name: step.name,
    actionType: step.actionType,
    status: isCurrent ? 'pending' : 'upcoming',
    eventType: null,
    occurredAt: null,
    dueAt,
    reason: null,
  };
});

return [{ json: { prospectId: row.prospectId, halted: row.halted, timeline } }];
